        _add(
            errors,
            path,
            "invalid_amount",
            f"{key} must be an unsigned decimal string with at most two fraction digits",
        )
        return None
    return Decimal(value)


def _money(value: Decimal) -> str:
    """金额统一输出两位小数。"""
    return str(value.quantize(_CENT))


